{   -- Mission successful, award a system key and do not offer the mission again
    0, nil, "Achieved",
    function( V, Data )
        NStar.StarUnlock( 19 )
        NPlayer.AddCredits( NPlayer.StandardReward() )
        return { Timeout=-1 }
    end
}

{
    1.001, 1.007, "ActionCamEnd",
    function( V, Data )
        if V.Cam == Data.Camera then
            V.Cam = nil
        end
    end
}

{
    1.001, 1.007, "ActionCamStart",
    function( V, Data )
        if V.Cam == Data.Camera then
            ...
        end
    end
}

{   -- Mission was created
    nil, nil, "Create",
    function( V, Data )
		-- do something
    end
}

{
    0, nil, "Failed", function( V, Data )
    if 100.0 == V.Step then
        return { Timeout = -1 }
    else
        return { Timeout = 0 }
    end
end }

{
    nil, nil, "Init", function( V, Data )
    local system = MissionLib.GetStarSystemId()
    if 12 == system 
	or 13 == system 
	or 14 == system 
	or 15 == system then
        V.System0   = 16;
        V.System1   = 12;
        V.System2   = 17;
        V.Pirates = {}
        return { Ready=true }
    end
    return { Ready=false }
end }

{
    nil, nil, "Subtype",
    function( V, Data )
        return { Subtype=SUBTYPE_POLITICAL }
    end
}

{   -- Show the logbook entry
    nil, nil, "Text", function( V, Data)
    if 1 > V.Step then
        return {
            Text = "IDM_HUMAN_003_LOG_CH01_0",
            Header = "IDM_HUMAN_003_HEADER",
            Client = "IDL_TRADER_02_0"..V.Combine,
            Replace = 
			{
                "IDM_HUMAN_003_TADENITNAME",
                "ID_SYSTEMNAME_"..V.StartsystemId 
			} }
    else
        return { Text = "IDM_HUMAN_003_LOG_CH01_1" }
    end
end }

